// Teamwork.com on an API key: every operation of the Projects API v3, plus v2 and v1 for what v3 doesn't have
// (messages, notebooks, links, invoices, expenses, webhooks...). actions.json is generated by
// `bun scripts/openapi-actions.ts teamwork`. The person pastes their site and API key on one line; calls go to their own
// <site>.teamwork.com with basic auth. Everything Teamwork's webhooks report starts automations (triggers.ts), and the
// activity feed is polled for people who can't set up webhooks (polls/teamwork.ts).
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

// "acme", "acme.teamwork.com", "acme.eu.teamwork.com" or a link into it
function host(raw: string) {
  const s = raw.trim().toLowerCase().replace(/^https?:\/\//, "").split("/")[0]!;
  const h = s.includes(".") ? s : `${s}.teamwork.com`;
  // only Teamwork's own hosts: the key decides where the API key is sent
  // ponytail: sites on a custom domain aren't accepted; their teamwork.com address still works
  if (!/^[a-z0-9][a-z0-9-]*\.(eu\.)?teamwork\.com$/.test(h)) throw new AppsError(`${raw} isn't a Teamwork.com address: use your site, like acme for acme.teamwork.com`);
  return h;
}

// The pasted line: the site and the API key, separated by a space, in either order.
export function parseKey(key: string) {
  const parts = key.trim().split(/\s+/).filter(Boolean);
  const site = parts.find((p) => /teamwork\.com|^https?:/i.test(p)) ?? [...parts].sort((a, b) => a.length - b.length)[0];
  const token = parts.find((p) => p !== site);
  if (parts.length !== 2 || !site || !token) throw new AppsError("paste two things separated by a space: your Teamwork.com site (acme for acme.teamwork.com) and your API key");
  return { host: host(site), token };
}

export const api: Api = {
  name: "Teamwork.com",
  base: "https://example.teamwork.com",
  tokenHelp: "your profile picture → Edit my details → API & Mobile",
  // the key is the username; Teamwork ignores the password
  auth: (key) => ({ Authorization: `Basic ${Buffer.from(`${parseKey(key).token}:x`).toString("base64")}`, Accept: "application/json" }),
  url: (key, _base, path) => `https://${parseKey(key).host}${path}`,
};

const ME = { method: "GET", path: "/projects/api/v3/me.json", query: [], headers: [] };

export const teamwork: OwnApp = {
  app: "teamwork",
  name: "Teamwork.com",
  logo: "/logos/teamwork.svg",
  keyField: {
    label: "Site and API key",
    help: "Paste two things on one line, separated by a space: 1) your Teamwork.com site, the first part of the address you open Teamwork at (acme for acme.teamwork.com; EU sites: acme.eu.teamwork.com); 2) your API key. To get the key, click your profile picture → Edit my details → API & Mobile, then show or generate your API key and copy it. Emplio can then do whatever your Teamwork user can. To have Emplio react the moment tasks, projects or comments change, use a site administrator's key on a paid plan.",
    placeholder: "acme tkn.v1_ABC123...",
  },
  async check(key) {
    const { host } = parseKey(key);
    const { person } = (await call(api, key, ME, {})) as { person?: { firstName?: string; lastName?: string; email?: string } };
    if (!person) throw new AppsError("Teamwork.com didn't accept that API key; check it and the site", true);
    const name = [person.firstName, person.lastName].filter(Boolean).join(" ") || person.email;
    return `${name} (${host})`;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
